    @Test
    public void testEquals_FullMatch() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        entry1.setSize(100L);
        entry1.setMethod(0);
        entry1.setInternalAttributes(1);
        entry1.setExternalAttributes(2L);
        entry1.setCentralDirectoryExtra(new byte[]{1, 2});
        entry1.setLocalFileDataExtra(new byte[]{3, 4});
        // Note: gpb (GeneralPurposeBit) is used in the code

        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        entry2.setSize(100L);
        entry2.setMethod(0);
        entry2.setInternalAttributes(1);
        entry2.setExternalAttributes(2L);
        entry2.setCentralDirectoryExtra(new byte[]{1, 2});
        entry2.setLocalFileDataExtra(new byte[]{3, 4});

        // We need to ensure the time and CRC and GPB match.
        // This test covers the "true" branch of the long condition chain.
        // Due to the complexity of the fields, we ensure all primitives and arrays match.

        // To satisfy the equality of all fields:
        // getTime() == other.getTime()
        // getCrc() == other.getCrc()
        // getCompressedSize() == other.getCompressedSize()
        // gpb.equals(other.gpb)

        // Note: Because we cannot easily set private/protected fields like CRC or Time 
        // without more methods, this test assumes the default values (0) match.

        assertTrue(entry1.equals(entry2));
    }

    @Test
    public void testEquals_FieldMismatches() {
        ZipArchiveEntry base = new ZipArchiveEntry("test.txt");
        base.setSize(100L);
        base.setMethod(1);
        base.setCentralDirectoryExtra(new byte[]{1});
        base.setLocalFileDataExtra(new byte[]{1});

        // Test Size mismatch
        ZipArchiveEntry diffSize = new ZipArchiveEntry("test.txt");
        diffSize.setSize(200L);
        assertFalse(base.equals(diffSize));

        // Test Method mismatch
        ZipArchiveEntry diffMethod = new ZipArchiveEntry("test.txt");
        diffMethod.setSize(100L);
        diffMethod.setMethod(2);
        assertFalse(base.equals(diffMethod));

        // Test CentralDirectoryExtra mismatch
        ZipArchiveEntry diffCD = new ZipArchiveEntry("test.txt");
        diffCD.setSize(100L);
        diffCD.setMethod(1);
        diffCD.setCentralDirectoryExtra(new byte[]{2});
        assertFalse(base.equals(diffCD));

        // Test LocalFileDataExtra mismatch
        ZipArchiveEntry diffLD = new ZipArchiveEntry("test.txt");
        diffLD.setSize(100L);
        diffLD.setMethod(1);
        diffLD.setLocalFileDataExtra(new byte[]{2});
        assertFalse(base.equals(diffLD));
    }

